"""Tests for the read-only machine-level accountability compliance export.

Covers `GET /machines/{machine_id}/accountability/compliance-export`: the
five accountability record groups (events, evidence, incidents, status
history, responsibility assignments), closed-UTC-window filtering per group,
ordering by the actual UTC instant then record id (exact-second records
before fractional-second records of the same second), verbatim export when a
related object is missing or misowned, the `bad_time` / `invalid_query` /
`not_found` outcomes, strict read-only byte stability, machine isolation, and
persistence across a restart.
"""
import uuid

import pytest
from fastapi.testclient import TestClient
from sqlalchemy import text

from accountability.app import app
from accountability.chain import backfill_chains


@pytest.fixture
def client(tmp_path, monkeypatch):
    monkeypatch.setenv(
        "ACCOUNTABILITY_DATABASE_URL", f"sqlite:///{tmp_path / 'test.db'}"
    )
    with TestClient(app) as test_client:
        yield test_client


WIDE = ("2000-01-01T00:00:00Z", "2100-01-01T00:00:00Z")

T0 = "2026-03-01T00:00:00Z"
T1 = "2026-03-01T00:00:01Z"
T2 = "2026-03-01T00:00:02Z"
T3 = "2026-03-01T00:00:03Z"
T4 = "2026-03-01T00:00:04Z"
T5 = "2026-03-01T00:00:05Z"


def export_url(machine_id, from_created_at=WIDE[0], to_created_at=WIDE[1]):
    return (
        f"/machines/{machine_id}/accountability/compliance-export"
        f"?from_created_at={from_created_at}&to_created_at={to_created_at}"
    )


def create_machine(client, external_id="machine-1"):
    response = client.post(
        "/machines",
        json={
            "external_id": external_id,
            "display_name": "Machine One",
            "public_key": "key-1",
        },
    )
    assert response.status_code == 201
    return response.json()["id"]


def allow_read(client, machine_id):
    client.post(
        f"/machines/{machine_id}/behavior-declarations",
        json={"action_type": "read", "resource_pattern": "res/*", "enabled": True},
    )
    client.post(
        "/policy-rules",
        json={
            "action_type": "read",
            "resource_pattern": "res/*",
            "effect": "allow",
            "priority": 0,
        },
    )


def record_event(client, machine_id, resource="res/1"):
    response = client.post(
        f"/machines/{machine_id}/authorization-decision-events",
        json={"action_type": "read", "resource": resource},
    )
    assert response.status_code == 201
    return response.json()


def attach_evidence(client, machine_id, event_id, evidence_type="log",
                    content_hash=None):
    response = client.post(
        f"/machines/{machine_id}/authorization-decision-events/"
        f"{event_id}/evidence",
        json={
            "evidence_type": evidence_type,
            "content_hash": content_hash or uuid.uuid4().hex * 2,
        },
    )
    assert response.status_code == 201
    return response.json()


def register_incident(client, machine_id, event_id,
                      incident_type="fault", summary="something failed"):
    response = client.post(
        f"/machines/{machine_id}/authorization-decision-events/"
        f"{event_id}/incidents",
        json={"incident_type": incident_type, "summary": summary},
    )
    assert response.status_code == 201
    return response.json()


def transition_incident(client, machine_id, event_id, incident_id, status):
    response = client.post(
        f"/machines/{machine_id}/authorization-decision-events/"
        f"{event_id}/incidents/{incident_id}/status",
        json={"status": status},
    )
    assert response.status_code == 200
    return response.json()

class IncidentOut(BaseModel):
    id: str
    machine_id: str
    event_id: str
    incident_type: str
    summary: str
    status: str
    created_at: str


def incident_to_out(record: AuthorizationDecisionIncident) -> IncidentOut:
    return IncidentOut(
        id=record.id,
        machine_id=record.machine_id,
        event_id=record.event_id,
        incident_type=record.incident_type,
        summary=record.summary,
        status=record.status,
        created_at=record.created_at,
    )


@app.post(
    "/machines/{machine_id}/authorization-decision-events/{event_id}/incidents",
    status_code=201,
    response_model=IncidentOut,
)
def create_incident(
    machine_id: str,
    event_id: str,
    body: IncidentCreate,
    session: SessionDep,
):
    """Register one persistent exception-handling incident on a decision event.

    Body validation runs before any path lookup, so a malformed payload is a
    422 even when the machine or event does not exist. The write touches only
    the incidents table: the event, its evidence, hash chain, and causal links
    are never modified.
    """
    event = get_machine_event(session, machine_id, event_id)
    if event is None:
        return error_response(404, "not_found")

    existing = session.scalar(
        select(AuthorizationDecisionIncident).where(
            AuthorizationDecisionIncident.event_id == event_id,
            AuthorizationDecisionIncident.incident_type == body.incident_type,
            AuthorizationDecisionIncident.summary == body.summary,
        )
    )
    if existing is not None:
        return error_response(409, "duplicate_incident")

    record = AuthorizationDecisionIncident(
        id=str(uuid.uuid4()),
        machine_id=machine_id,
        event_id=event_id,
        incident_type=body.incident_type,
        summary=body.summary,
        status="open",
        created_at=utc_now_iso(),
    )
    session.add(record)
    try:
        session.commit()
    except IntegrityError:
        session.rollback()
        return error_response(409, "duplicate_incident")
    return incident_to_out(record)


@app.get(
    "/machines/{machine_id}/authorization-decision-events/{event_id}/incidents",
    response_model=list[IncidentOut],
)
def list_incidents(machine_id: str, event_id: str, session: SessionDep):
    event = get_machine_event(session, machine_id, event_id)
    if event is None:
        return error_response(404, "not_found")

    records = session.scalars(
        select(AuthorizationDecisionIncident)
        .where(
            AuthorizationDecisionIncident.machine_id == machine_id,
            AuthorizationDecisionIncident.event_id == event_id,
        )
        .order_by(
            AuthorizationDecisionIncident.created_at,
            AuthorizationDecisionIncident.id,
        )
    ).all()
    return [incident_to_out(record) for record in records]


class IncidentStatusUpdate(BaseModel):
    status: Literal["acknowledged", "resolved"]


class IncidentStatusEventOut(BaseModel):
    id: str
    machine_id: str
    event_id: str
    incident_id: str
    from_status: str
    to_status: str
    created_at: str


def incident_status_event_to_out(
    record: IncidentStatusEvent,
) -> IncidentStatusEventOut:
    return IncidentStatusEventOut(
        id=record.id,
        machine_id=record.machine_id,
        event_id=record.event_id,
        incident_id=record.incident_id,
        from_status=record.from_status,
        to_status=record.to_status,
        created_at=record.created_at,
    )


class IncidentStatusEventChainOut(IncidentStatusEventOut):
    # The status-history listing adds the tamper-evident chain fields; the
    # compliance exports keep the 7-field shape above.
    previous_status_event_id: str | None
    content_hash: str | None
    chain_hash: str | None

